import org.apache.commons.lang3.time.DurationFormatUtils;
import java.util.Calendar;
import java.util.TimeZone;

public class Scratch {
    public static void main(String[] args) throws Exception {
        TimeZone gmt = TimeZone.getTimeZone("GMT");
        Calendar startCal = Calendar.getInstance(gmt);
        startCal.clear();
        startCal.set(2020, Calendar.JANUARY, 15, 0, 0, 0);
        Calendar endCal = Calendar.getInstance(gmt);
        endCal.clear();
        endCal.set(2020, Calendar.MARCH, 10, 0, 0, 0);
        System.out.println("period M/d: " + DurationFormatUtils.formatPeriod(startCal.getTimeInMillis(), endCal.getTimeInMillis(), "M' months, 'd' days'", true, gmt));

        System.out.println("duration 1d pattern: " + DurationFormatUtils.formatDuration(86400000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("duration 1h pattern: " + DurationFormatUtils.formatDuration(3600000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("duration 1m pattern: " + DurationFormatUtils.formatDuration(60000L, "d'd'[H'h'm'm']s's'"));
        System.out.println("duration 0 pattern: " + DurationFormatUtils.formatDuration(0L, "d'd'[H'h'm'm']s's'"));

        System.out.println("HMS 0: " + DurationFormatUtils.formatDurationHMS(0));
        System.out.println("HMS 3661789: " + DurationFormatUtils.formatDurationHMS(3661789));
        System.out.println("duration noPad: " + DurationFormatUtils.formatDuration(3661005L, "H:m:s.S", false));

        System.out.println("words 0,false,false: [" + DurationFormatUtils.formatDurationWords(0, false, false) + "]");
        System.out.println("words 0,true,true: [" + DurationFormatUtils.formatDurationWords(0, true, true) + "]");
        System.out.println("words 3661000,false,false: [" + DurationFormatUtils.formatDurationWords(3661000, false, false) + "]");
        System.out.println("words 3661000,true,false: [" + DurationFormatUtils.formatDurationWords(3661000, true, false) + "]");

        System.out.println("ISO duration 0: " + DurationFormatUtils.formatDurationISO(0));
        System.out.println("ISO duration 3661005: " + DurationFormatUtils.formatDurationISO(3661005));

        System.out.println("ISO period same: " + DurationFormatUtils.formatPeriodISO(startCal.getTimeInMillis(), startCal.getTimeInMillis()));
        System.out.println("ISO period: " + DurationFormatUtils.formatPeriodISO(startCal.getTimeInMillis(), endCal.getTimeInMillis()));

        try {
            DurationFormatUtils.formatDuration(-1, "HH:mm:ss.SSS");
            System.out.println("NO EXCEPTION for negative duration");
        } catch (IllegalArgumentException e) {
            System.out.println("negative duration ex: " + e.getMessage());
        }

        try {
            DurationFormatUtils.formatPeriod(100, 0, "HH:mm:ss.SSS");
            System.out.println("NO EXCEPTION for start>end");
        } catch (IllegalArgumentException e) {
            System.out.println("start>end ex: " + e.getMessage());
        }

        try {
            DurationFormatUtils.formatDuration(0, "[[s]]");
            System.out.println("NO EXCEPTION nested");
        } catch (IllegalArgumentException e) {
            System.out.println("nested ex: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "]");
            System.out.println("NO EXCEPTION unopened");
        } catch (IllegalArgumentException e) {
            System.out.println("unopened ex: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "'abc");
            System.out.println("NO EXCEPTION unmatched quote");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched quote ex: " + e.getMessage());
        }
        try {
            DurationFormatUtils.formatDuration(0, "[s");
            System.out.println("NO EXCEPTION unmatched optional");
        } catch (IllegalArgumentException e) {
            System.out.println("unmatched optional ex: " + e.getMessage());
        }

        System.out.println("duration 0, HH:mm:ss.SSS: " + DurationFormatUtils.formatDuration(0L, "HH:mm:ss.SSS"));
        System.out.println("literal double quote: " + DurationFormatUtils.formatDuration(5000L, "s''s' seconds'"));
    }
}
